/**
 * setLeftTop - places an object by its visual left/top regardless of origin.
 */
export function setLeftTop<T extends PosObject>(item: T, left: number, top: number): T {
  const bounds = item.getBounds();
  const dX = left - bounds.left;
  const dY = top - bounds.top;
  item.setPosition(item.x + dX, item.y + dY);
  return item;
}

/**
 * Creates a container with optional logical size.
 */
export function con(
    scene: Phaser.Scene,
    x = 0,
    y = 0,
    width = 0,
    height = 0,
): Phaser.GameObjects.Container {
  const container = scene.add.container(x, y);
  container.setSize(width, height);
  return container;
}

/**
 * Creates a container from declarative view data.
 */
export function createContainerFromViewData(
  scene: Phaser.Scene,
  view: IAutoViewData,
): Phaser.GameObjects.Container {
  const root = con(scene, 0, 0, view.width, view.height);
  root.name = view.name || "";
  root.setSize(view.width, view.height);

  if(view.button){
    root.setData("button", true);

    /** должно идти после setSize! **/
    root.setInteractive({
      useHandCursor: true,
    });
  }

  return root;
}

/**
 * Adds an atlas image and positions it by Figma coordinates.
 */
export function addAssetImage(props: IAddAssetImageProps): Phaser.GameObjects.Image {
  const { scene, asset, x, y } = props;
  const targetX = x ?? asset.x;
  const targetY = y ?? asset.y;
  const imageNode = scene.add.image(0, 0, asset.url, asset.frameName);
  imageNode.name = asset.name || "";
  return setLeftTop(imageNode, targetX, targetY);
}

/**
 * Adds a nine-slice object and positions it by Figma coordinates.
 */
export function addAssetNine(props: IAddAssetNineProps): Phaser.GameObjects.NineSlice {
  const { scene, asset, width, height, x, y } = props;
  const padding = asset.ninePadding ?? 20;
  const targetWidth = width ?? asset.width;
  const targetHeight = height ?? asset.height;
  const targetX = x ?? asset.x;
  const targetY = y ?? asset.y;

  const nineSliceNode = scene.add.nineslice(
      0,
      0,
      asset.url,
      asset.frameName,
      targetWidth,
      targetHeight,
      padding,
      padding,
      padding,
      padding,
  );

  nineSliceNode.name = asset.name || "";
  return setLeftTop(nineSliceNode, targetX, targetY);
}

/**
 * Resolves localized text by locale key with fallback chain.
 */
function resolveLocaleText(
  localeMap: IAutoTextData["localeMap"],
  locale?: string,
): string {
  const requestedLocale = String(locale || "en");
  const nextText =
    localeMap[requestedLocale] ??
    localeMap.en ??
    localeMap.ru ??
    "";

  return String(nextText || "");
}

/**
 * Creates a Phaser Text object from declarative text data.
 */
export function createTextView(
  scene: Phaser.Scene,
  textData: IAutoTextData,
  options: ITextViewOptions = {},
): Phaser.GameObjects.Text {
  const style = {
    ...textData.style,
    ...(options.style || {}),
  };
  const hasStaticTextOverride = typeof options.text === "string";
  const initialText = hasStaticTextOverride
    ? String(options.text || "")
    : resolveLocaleText(textData.localeMap, options.locale);

  const textObject = scene.add.text(0, 0, initialText, style);
  textObject.name = textData.name || "";
  textObject.setOrigin(0, 0);
  textObject.setPosition(textData.x || 0, textData.y || 0);

  if (!hasStaticTextOverride) {
    const localeListener = (payload: { locale?: string } | string | null | undefined) => {
      const locale =
        payload && typeof payload === "object"
          ? payload.locale
          : typeof payload === "string"
            ? payload
            : undefined;
      textObject.setText(resolveLocaleText(textData.localeMap, locale));
    };

    scene.events.on("onLocaleChange", localeListener);
    textObject.once(Phaser.GameObjects.Events.DESTROY, () => {
      scene.events.off("onLocaleChange", localeListener);
    });
  }

  return textObject;
}

/**
 * Creates an asset child from declarative child data.
 */
export function createAssetChild(
  scene: Phaser.Scene,
  child: IAutoViewAssetChildData,
): PosGameObject {
  if (child.asset.kind === "nine") {
    return addAssetNine({
      scene,
      asset: child.asset,
      width: child.width,
      height: child.height,
      x: child.x,
      y: child.y,
    });
  }

  return addAssetImage({
    scene,
    asset: child.asset,
    x: child.x,
    y: child.y,
  });
}

/**
 * Creates a text child from declarative child data.
 */
export function createTextChild(
  scene: Phaser.Scene,
  child: IAutoTextRefChildData,
): Phaser.GameObjects.Text {
  const textNode = createTextView(scene, child.text);
  textNode.setPosition(child.x, child.y);
  return textNode;
}

/**
 * Adds a child to a generated view using the same center correction as createView.
 */
export function addChildToView(
  view: Phaser.GameObjects.Container,
  child: PosGameObject,
  viewData: IAutoViewData,
): void {
  child.x -= viewData.width/2;
  child.y -= viewData.height/2;
  view.add(child);
}

/**
 * Positions and adds a nested view child using declarative child data.
 */
export function addNestedViewToView(
  view: Phaser.GameObjects.Container,
  child: PosGameObject,
  viewData: IAutoViewData,
  childData: IAutoViewRefChildData,
): void {
  setLeftTop(child, childData.x, childData.y);
  addChildToView(view, child, viewData);
}

/**
 * Creates a Phaser container from declarative view data.
 */
export function createView(scene: Phaser.Scene, view: IAutoViewData): Phaser.GameObjects.Container {
  const root = createContainerFromViewData(scene, view);

  view.children.forEach((child) => {
    const viewChild = renderViewChild(scene, child);

    addChildToView(root, viewChild, view);
  });

  return root;
}

/**
 * Renders a view child using the shared asset helpers.
 */
export function renderViewChild(
  scene: Phaser.Scene,
  child: IAutoViewChildData,
): PosGameObject {
  if (child.type === "view") {
    const nestedView = createView(scene, child.view);
    setLeftTop(nestedView, child.x, child.y);
    return nestedView;
  }

  if (child.type === "text") {
    const textNode = createTextView(scene, child.text);
    textNode.setPosition(child.x, child.y);
    return textNode;
  }

  if (child.asset.kind === "nine") {
    return addAssetNine({
      scene,
      asset: child.asset,
      width: child.width,
      height: child.height,
      x: child.x,
      y: child.y,
    });
  }

  return addAssetImage({
    scene,
    asset: child.asset,
    x: child.x,
    y: child.y,
  });
}
